#!/usr/bin/env python3
"""Collect immutable T10 evidence after all MATLAB/timing queues are idle.

Uses only Python's standard library. Source files are read without modification.
New report destinations must not exist. Run without redirecting this collector's
output into the evidence root: such a log would change during its own hash.
"""

import argparse
import collections
import csv
import datetime
import hashlib
import json
import math
import os
from pathlib import Path
import re
import shlex
import shutil
import subprocess
import sys


def utc_time(timestamp):
    return datetime.datetime.fromtimestamp(timestamp, datetime.timezone.utc).isoformat()


def write_json(path, value):
    path.write_text(json.dumps(value, indent=2, ensure_ascii=False, allow_nan=False) + "\n", encoding="utf-8")


def write_csv(path, rows, fields):
    with path.open("w", encoding="utf-8", newline="") as stream:
        writer = csv.DictWriter(stream, fieldnames=fields, lineterminator="\n")
        writer.writeheader()
        writer.writerows(rows)


def assert_no_active_jobs():
    result = subprocess.run(["/bin/ps", "-axo", "pid=,comm=,args="], check=True, capture_output=True, text=True)
    found = []
    for line in result.stdout.splitlines():
        parts = line.strip().split(None, 2)
        if len(parts) != 3 or int(parts[0]) == os.getpid():
            continue
        try:
            arguments = shlex.split(parts[2])
        except ValueError:
            continue
        names = {Path(argument).name for argument in arguments}
        matlab_batch = "-batch" in arguments and bool(names & {"matlab", "MATLAB"})
        queue = bool(names & {"guardThermalReadiness.py", "guard_matlab.py", "regimeQueue.py", "resolutionQueue.py", "completionQueue.py", "finalMeasurements.py"})
        if matlab_batch or queue:
            found.append(line.strip())
    if found:
        raise RuntimeError("Wait until MATLAB batches and timing queues are idle before collecting:\n" + "\n".join(found))


def source_files(root):
    files, skipped = [], []
    for directory, folders, names in os.walk(root, followlinks=False):
        directory = Path(directory)
        retained = []
        for name in sorted(folders):
            path = directory / name
            if path.is_symlink() or name in {".git", "__pycache__"} or path == root / "pinned":
                skipped.append(str(path.relative_to(root)))
            else:
                retained.append(name)
        folders[:] = retained
        for name in sorted(names):
            path = directory / name
            if path.is_symlink() or not path.is_file():
                skipped.append(str(path.relative_to(root)))
            else:
                files.append(path)
    provenance = root / "pinned" / "provenance.json"
    if not provenance.is_file():
        raise FileNotFoundError("Historical worktree tree is excluded; its required provenance is missing: " + str(provenance))
    files.append(provenance)
    return sorted(files), skipped


def hash_file(path):
    before = path.stat()
    digest = hashlib.sha256()
    with path.open("rb") as stream:
        for chunk in iter(lambda: stream.read(1024 * 1024), b""):
            digest.update(chunk)
    after = path.stat()
    if (before.st_size, before.st_mtime_ns) != (after.st_size, after.st_mtime_ns):
        raise RuntimeError("Source changed while hashing; collection is not final: " + str(path))
    return after, digest.hexdigest()


def outcome(result):
    if result is None:
        return "completion-unrecorded"
    reason, code = result.get("reason"), result.get("returncode")
    if reason == "memory-limit":
        return "memory-cutoff"
    if reason == "wall-limit":
        return "wall-cutoff"
    if reason == "cancelled":
        return "cancelled"
    if reason == "completed" and code == 0:
        return "completed-process"
    if code not in (None, 0):
        return "failed-process"
    return "guard-error-or-unresolved"


def guard_records(root):
    records = []
    for path in sorted((root / "recovery").rglob("contract.json")):
        contract = json.loads(path.read_text())
        if not isinstance(contract, dict) or not isinstance(contract.get("command"), list):
            continue
        result_path = path.with_name("result.json")
        result = json.loads(result_path.read_text()) if result_path.is_file() else None
        command = contract["command"]
        is_matlab = "-batch" in command and any(Path(str(token)).name in {"matlab", "MATLAB"} for token in command)
        nested = any((parent / "contract.json").is_file() for parent in path.parent.parents if parent != root and root in parent.parents)
        records.append(dict(directory=str(path.parent.relative_to(root)), contract=contract, result=result,
                            outcome=outcome(result), matlabBatch=is_matlab, nestedUnderRecordedGuard=nested))
    return records


def script_records(root, records):
    direct = collections.defaultdict(list)
    run_pattern = re.compile(r"\brun\(\s*(['\"])(.*?)\1\s*\)")
    for record in records:
        for argument in record["contract"]["command"]:
            for match in run_pattern.finditer(str(argument)):
                requested = Path(match.group(2))
                if requested.is_absolute():
                    direct[str(requested)].append(record["directory"])
    scripts = []
    for path in sorted((root / "recovery").rglob("*")):
        if not path.is_file() or path.is_symlink() or path.suffix not in {".m", ".py"}:
            continue
        data = path.read_bytes()
        source = data.decode("utf-8")
        references = [match.group(2) for match in run_pattern.finditer(source)]
        scripts.append(dict(path=str(path.relative_to(root)), bytes=len(data), sha256=hashlib.sha256(data).hexdigest(),
                            lastModifiedUTC=utc_time(path.stat().st_mtime), requestedByGuardDirectories=direct.get(str(path), []),
                            literalRunReferences=references, source=source))
    invoked = {str(root / script["path"]) for script in scripts if script["requestedByGuardDirectories"]}
    reachable = set(invoked)
    changed = True
    while changed:
        changed = False
        for script in scripts:
            if str(root / script["path"]) in reachable:
                for reference in script["literalRunReferences"]:
                    target = str(Path(reference)) if Path(reference).is_absolute() else str((root / script["path"]).parent / reference)
                    if target not in reachable:
                        reachable.add(target)
                        changed = True
    for script in scripts:
        path = str(root / script["path"])
        script["invocationEvidence"] = "requested-in-recorded-guard-command" if path in invoked else "literal-helper-of-requested-script" if path in reachable else "present-without-recorded-invocation"
    return scripts


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    inferred = Path(__file__).resolve().parent.parent
    parser.add_argument("--evidence-root", type=Path, default=inferred)
    parser.add_argument("--report-root", type=Path, default=inferred.parent / "wave-vortex-model/Documentation/Validation/Issue441")
    parser.add_argument("--copy-subdir", default="evidence")
    parser.add_argument("--artifact-index", default="artifacts.csv")
    parser.add_argument("--max-copy-bytes", type=int, default=2 * 1024 * 1024)
    args = parser.parse_args()
    root, report = args.evidence_root.resolve(), args.report_root.resolve()
    if not root.is_dir() or not report.is_dir() or args.max_copy_bytes <= 0:
        parser.error("Use existing evidence/report roots and a positive copy limit.")
    if root == report or root in report.parents or report in root.parents:
        parser.error("Evidence and report roots must be separate non-nested directories.")
    for value in (args.copy_subdir, args.artifact_index):
        if Path(value).name != value or value in {".", ".."}:
            parser.error("Output names must be single path components.")
    copies, index = report / args.copy_subdir, report / args.artifact_index
    if copies == index:
        parser.error("The evidence directory and artifact CSV need different names.")
    if copies.exists() or index.exists():
        parser.error("Use new output names; existing evidence is never overwritten.")
    assert_no_active_jobs()
    files, skipped = source_files(root)
    records = guard_records(root)
    scripts = script_records(root, records)
    artifacts = []
    for number, path in enumerate(files, 1):
        stat, digest = hash_file(path)
        artifacts.append(dict(path=str(path.relative_to(root)), bytes=stat.st_size, sha256=digest,
                              lastModifiedUTC=utc_time(stat.st_mtime), fileType=path.suffix.lower().lstrip(".") or "unclassified"))
        if number % 100 == 0:
            print(f"Hashed {number}/{len(files)} retained files", flush=True)
    indexed_hashes = {row["path"]: row["sha256"] for row in artifacts}
    for script in scripts:
        if indexed_hashes.get(script["path"]) != script["sha256"]:
            raise RuntimeError("Script changed while collecting its source: " + script["path"])
    assert_no_active_jobs()
    copies.mkdir()
    copied, omitted_small = [], []
    for row in artifacts:
        path = root / row["path"]
        if path.suffix.lower() not in {".csv", ".json"}:
            continue
        if path.suffix.lower() == ".json" and row["bytes"] == 0:
            omitted_small.append(dict(path=row["path"], reason="empty-failed-json-retained-external"))
            continue
        if row["bytes"] > args.max_copy_bytes or path.name == "memory.csv":
            omitted_small.append(dict(path=row["path"], reason="size-limit" if row["bytes"] > args.max_copy_bytes else "raw-memory-samples-remain-external"))
            continue
        target = copies / "raw" / row["path"]
        target.parent.mkdir(parents=True, exist_ok=True)
        shutil.copyfile(path, target)
        copied_stat, copied_digest = hash_file(target)
        if (copied_stat.st_size, copied_digest) != (row["bytes"], row["sha256"]):
            raise RuntimeError("Source changed before copying; partial destination is retained: " + str(path))
        copied.append(dict(sourcePath=row["path"], copiedPath=str(target.relative_to(report)), bytes=row["bytes"], sourceSHA256=row["sha256"], copySHA256=copied_digest))
    write_csv(copies / "source-copy-index.csv", copied, ["sourcePath", "copiedPath", "bytes", "sourceSHA256", "copySHA256"])
    write_json(copies / "guard-executions.json", dict(schema="t10-guard-executions-v1", scope="Process outcomes only; inspect scientific CSV/JSON acceptance separately. A missing result is not completion.", records=records))
    write_json(copies / "recovery-script-sources.json", dict(schema="t10-recovery-script-sources-v1",
        scope="Retained source at collection time. Guard contracts prove requested commands, not that every script/helper line ran. Source bytes were not independently locked at each historical invocation; present-only scripts are not executed evidence.", scripts=scripts))
    totals = {"recordedMatlabGuardElapsedSeconds": 0.0, "recordedOtherGuardElapsedSeconds": 0.0}
    outcome_counts = collections.Counter(record["outcome"] for record in records)
    for record in records:
        elapsed = (record["result"] or {}).get("elapsedSeconds")
        if record["nestedUnderRecordedGuard"] or not isinstance(elapsed, (int, float)) or not math.isfinite(elapsed):
            continue
        key = "recordedMatlabGuardElapsedSeconds" if record["matlabBatch"] else "recordedOtherGuardElapsedSeconds"
        totals[key] += elapsed
    write_json(copies / "collection.json", dict(schema="t10-final-artifacts-v1", collectedAtUTC=utc_time(datetime.datetime.now().timestamp()),
        evidenceRoot=str(root), reportRoot=str(report), filesHashed=len(artifacts), smallFilesCopied=len(copied), skippedTreesOrLinks=skipped,
        omittedSmallFiles=omitted_small, guardOutcomeCounts=dict(outcome_counts), elapsed=totals,
        elapsedScope="Sums of available post-restart, non-nested guard elapsed times, including startup, failures and cutoffs. Not CPU time, total task lifetime, or proof of the study budget; overlapping jobs and unguarded work are not reconstructed. Lost pre-reboot time is unmeasured here.",
        pinScope="Detached historical checkout payloads are excluded; pinned/provenance.json records their exact revisions and setup-file hashes.",
        artifactScope="All regular retained evidence files, including MAT/NetCDF/logs/scripts, are hashed outside git. Small CSV/JSON copies preserve original bytes; generated indexes use LF. No scientific outcome is promoted by process completion."))
    write_csv(index, artifacts, ["path", "bytes", "sha256", "lastModifiedUTC", "fileType"])
    print(f"Collected {len(copied)} small evidence files; indexed {len(artifacts)} persistent artifacts.")


if __name__ == "__main__":
    try:
        main()
    except Exception as exception:
        print(f"Collection failed: {type(exception).__name__}: {exception}", file=sys.stderr)
        sys.exit(1)

