function value=jsonReady(value)
% Original MAT files remain authoritative; preserve complex data explicitly.
if isstruct(value)
    names=fieldnames(value);
    for k=1:numel(value)
        for j=1:numel(names),value(k).(names{j})=jsonReady(value(k).(names{j}));end
    end
elseif iscell(value)
    for k=1:numel(value),value{k}=jsonReady(value{k});end
elseif isnumeric(value) && ~isreal(value)
    value=struct(jsonEncoding="complex array",shape=size(value),real=real(value),imaginary=imag(value));
elseif isa(value,'function_handle')
    value=struct(jsonEncoding="function text only; see authoritative MAT for closure",text=string(func2str(value)));
end
end

